  ESLINT_VERDICT, OWN_GIT_AFTER, OWN_GIT_BEFORE, eslintStep, frozenStep, fullArgs, heredoc, namesKept, snapshotLines,
  tscStep, untrackedStep, vitestStep, wrapScript,
