    .toBe('[ "$E" = 0 ] || { echo "== eslint failed (see above); every step between it and here passed"; exit 1; }\n');
  expect(OWN_GIT_BEFORE.split("\n")).toHaveLength(2);
  expect(OWN_GIT_AFTER.startsWith("echo '== own git'; G1=$( ")).toBe(true);
